window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-51496e42b654b4ca"]={"versions": [{"id": "FIG-51496e42b654b4ca", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Veranschaulichung einer VFB-basierten Timing-Kette (TimingChain) bei Client-Server-Kommunikation in der AUTOSAR Virtual Function Bus (VFB) Spezifikation. Dargestellt wird die zeitliche Abfolge und die Erreichbarkeit von Operationsaufrufen und Serverantworten über Portgrenzen hinweg.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Lebenslinien / Instanzen:</li>\n<li><code>client</code>: Aufrufende Software-Komponente bzw. Client-Entität mit Require-Port.</li>\n<li><code>VFB</code>: Virtueller Funktionsbus als Vermittlungsschicht für die Inter-Port-Kommunikation.</li>\n<li><code>server</code>: Ausführende Software-Komponente bzw. Server-Entität mit Provide-Port.</li>\n<li>VFB-Timing-Ereignisse / Beschriftungs-Notizen (Annotationen an den Kommunikationsschritten):</li>\n<li><code>ClientInvocationAvailableOnRPort</code>: Bereitstellung des Aufrufs am Require-Port des Clients.</li>\n<li><code>ClientInvocationAvailableOnPPort</code>: Weiterleitung und Verfügbarkeit des Aufrufs am Provide-Port des Servers.</li>\n<li><code>ServerResponseAvailableOnPPort</code>: Bereitstellung des Ausführungsergebnisses am Provide-Port des Servers.</li>\n<li><code>ServerResponseAvailableOnRPort</code>: Rückübermittlung und Verfügbarkeit des Ergebnisses am Require-Port des Clients.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><code>client</code> initiiert den Operationsaufruf; das Ereignis <code>ClientInvocationAvailableOnRPort</code> tritt ein. Eine synchrone oder vermittelte Aufrufnachricht geht an den <code>VFB</code>.</li>\n<li>Während der <code>client</code> aktiv blockiert bleibt, leitet der <code>VFB</code> den Aufruf asynchron bzw. gerichtet an den <code>server</code> weiter; dabei wird <code>ClientInvocationAvailableOnPPort</code> signalisiert.</li>\n<li>Der <code>server</code> wird aktiviert und führt die Operation aus.</li>\n<li>Nach Abschluss sendet der <code>server</code> eine Antwortnachricht (gestrichelter Pfeil) zurück an den <code>VFB</code>; dabei tritt <code>ServerResponseAvailableOnPPort</code> ein. Der Aktivierungsbalken des Servers endet.</li>\n<li>Der <code>VFB</code> übermittelt die Antwort an den <code>client</code> (gestrichelter Pfeil), markiert durch <code>ServerResponseAvailableOnRPort</code>. Mit Empfang endet der Aktivierungsbalken des Clients.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die normativen Beobachtungspunkte bzw. VFB-Timing-Events für Client-Server-Operationen zur Definition und Messung von Latenzzeiten in Timing-Ketten (Timing Chains). Für die AUTOSAR-Timing-Modellierung markieren diese Events die standardisierten Schnittstellen- und Übergangszeitpunkte zwischen Software-Komponenten und der VFB-Infrastruktur.</p>"}, {"id": "FIG-3f58192725463cde", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Veranschaulichung einer VFB-basierten Timing-Kette (TimingChain) bei Client-Server-Kommunikation in der AUTOSAR Virtual Function Bus (VFB) Spezifikation. Dargestellt wird die zeitliche Abfolge und die Erreichbarkeit von Operationsaufrufen und Serverantworten über Portgrenzen hinweg.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Lebenslinien / Instanzen:</li>\n<li><code>client</code>: Aufrufende Software-Komponente bzw. Client-Entität mit Require-Port.</li>\n<li><code>VFB</code>: Virtueller Funktionsbus als Vermittlungsschicht für die Inter-Port-Kommunikation.</li>\n<li><code>server</code>: Ausführende Software-Komponente bzw. Server-Entität mit Provide-Port.</li>\n<li>VFB-Timing-Ereignisse / Beschriftungs-Notizen (Annotationen an den Kommunikationsschritten):</li>\n<li><code>ClientInvocationAvailableOnRPort</code>: Bereitstellung des Aufrufs am Require-Port des Clients.</li>\n<li><code>ClientInvocationAvailableOnPPort</code>: Weiterleitung und Verfügbarkeit des Aufrufs am Provide-Port des Servers.</li>\n<li><code>ServerResponseAvailableOnPPort</code>: Bereitstellung des Ausführungsergebnisses am Provide-Port des Servers.</li>\n<li><code>ServerResponseAvailableOnRPort</code>: Rückübermittlung und Verfügbarkeit des Ergebnisses am Require-Port des Clients.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><code>client</code> initiiert den Operationsaufruf; das Ereignis <code>ClientInvocationAvailableOnRPort</code> tritt ein. Eine synchrone oder vermittelte Aufrufnachricht geht an den <code>VFB</code>.</li>\n<li>Während der <code>client</code> aktiv blockiert bleibt, leitet der <code>VFB</code> den Aufruf asynchron bzw. gerichtet an den <code>server</code> weiter; dabei wird <code>ClientInvocationAvailableOnPPort</code> signalisiert.</li>\n<li>Der <code>server</code> wird aktiviert und führt die Operation aus.</li>\n<li>Nach Abschluss sendet der <code>server</code> eine Antwortnachricht (gestrichelter Pfeil) zurück an den <code>VFB</code>; dabei tritt <code>ServerResponseAvailableOnPPort</code> ein. Der Aktivierungsbalken des Servers endet.</li>\n<li>Der <code>VFB</code> übermittelt die Antwort an den <code>client</code> (gestrichelter Pfeil), markiert durch <code>ServerResponseAvailableOnRPort</code>. Mit Empfang endet der Aktivierungsbalken des Clients.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die normativen Beobachtungspunkte bzw. VFB-Timing-Events für Client-Server-Operationen zur Definition und Messung von Latenzzeiten in Timing-Ketten (Timing Chains). Für die AUTOSAR-Timing-Modellierung markieren diese Events die standardisierten Schnittstellen- und Übergangszeitpunkte zwischen Software-Komponenten und der VFB-Infrastruktur.</p>"}], "trans": [{"from": "FIG-51496e42b654b4ca", "to": "FIG-3f58192725463cde", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Unterer Rückkehrpfeil (<code>ServerResponseAvailableOnRPort</code>): Die Pfeilspitze trifft den Aktivierungsbalken der Lebenslinie <code>client</code> leicht versetzt (der untere Schenkel der Pfeilspitze ragt links minimal über den Aktivierungsbalken hinaus).</li>\n<li>Bildbeschnitt: Geringfügig reduzierter Weißraum am unteren Bildrand (Höhe 453 px statt 474 px).</li>\n</ul>"}]};
